    if (expected_write_cursor > 0) {
        assert_byte_from_buffer_matches(stuffer->blob.data, &old_byte);
    }

    /* Everything after the new write cursor should be wiped */
    if (expect_wiped > 0) {
        assert_all_bytes_are(stuffer->blob.data + stuffer->write_cursor,
